            byte bits = 0;
            if (paint) bits |= HallValue.Paint;
            if (tramp) bits |= HallValue.Tramp;
            int g0 = (trainNo * 3 + 2) % Mathf.Max(1, n);
            if (gold && OnePitBalance.TrainGold > 0 && ((k - g0 + n) % n) < OnePitBalance.TrainGold) bits |= HallValue.Gold;
            return bits;
        }

