    public sealed class OnePitTrainShotsTest : ITestScene
    {
        public string Name => "OnePitTrainShots";
        public void Build() => new GameObject("OnePitTrainShotsTest").AddComponent<OnePitTrainShotsDriver>();
    }

    public sealed class OnePitTrainShotsDriver : OnePit8bDriver
    {
        protected override string Id => "OnePitTrainShots";
        protected override float Timeout => 120f;

        IEnumerator Start()
        {
            yield return BeginHall();
            var hero = Game.Player; var cs = CarryStack.Instance;
            if (hero == null || cs == null || HallTrain.I == null) { Summary(); yield break; }
            HallUx.Flags |= HallUx.FThrow;
            HallUpgrades.DebugSet(HallUpgrades.Stack, 4);
            HallThrow.QaAutoAim(true);
            OnePitState.HallTimeD = OnePitBalance.TrainFirst + 1.0;
            Put(new Vector3(-2f, 0f, -12f), 0f);
            for (float t = 0f; t < 3f && !HallTrain.Running; t += TimeCtl.Dt) yield return null;
            yield return Wait(1.0f);                        // вышла, бежит
            // герой идёт наперерез по дорожке до касания
            for (float t = 0f; t < 9f && HallTrain.Running; t += TimeCtl.Dt)
            {
                var m = HallTrain.MemberPos(Mathf.Max(0, HallTrain.NearestIn(hero.Position)));
                var to = (m - hero.Position); to.y = 0f;
                if (to.sqrMagnitude > 0.05f) hero.Teleport(hero.Position + to.normalized * Mathf.Min(to.magnitude, 6.5f * TimeCtl.Dt), Mathf.Atan2(to.x, to.z) * Mathf.Rad2Deg);
                yield return null;
            }
            // подбор россыпи
            for (float tg = 0f; tg < 8f && HallTrain.ScatterPicked < HallTrain.ScatterN; tg += TimeCtl.Dt)
            {
                if (HallTrain.ScatterLeft(hero.Position, out var dp))
                {
                    var to = dp - hero.Position; to.y = 0f;
                    if (to.sqrMagnitude > 0.04f) hero.Teleport(hero.Position + to.normalized * Mathf.Min(to.magnitude, 5.5f * TimeCtl.Dt), Mathf.Atan2(to.x, to.z) * Mathf.Rad2Deg);
                }
                yield return null;
            }
            yield return Wait(1.2f);
            // к Яме и бросок
            var pit = Game.Pit;
            if (pit != null)
            {
                var goal = new Vector3(0f, 0f, -(pit.Radius + 1.5f));
                for (float t = 0f; t < 4f; t += TimeCtl.Dt)
                {
                    var to = goal - hero.Position; to.y = 0f;
                    if (to.magnitude < 0.2f) break;
                    hero.Teleport(hero.Position + to.normalized * Mathf.Min(to.magnitude, 7f * TimeCtl.Dt), Mathf.Atan2(to.x, to.z) * Mathf.Rad2Deg);
                    yield return null;
                }
                HallThrow.Do("test");
            }
            yield return Wait(4f);
            // второй паровозик: бросок «Кинуть» в строй
            HallTrain.QaSpawn(-1);
            yield return Wait(0.2f);
            HallTrain.QaHead(9f);
            yield return null;
            yield return Fill(6);
            HallTrain.FuturePos(3, OnePitBalance.TrainThrowFlySec, out var aim);
            float sgn = HallTrain.LaneZ >= 0f ? 1f : -1f;
            Put(new Vector3(aim.x, 0f, aim.z - sgn * HallThrow.Range), sgn > 0 ? 0f : 180f);
            yield return null;
            HallTrain.FuturePos(3, OnePitBalance.TrainThrowFlySec, out aim);
            Put(new Vector3(aim.x, 0f, aim.z - sgn * HallThrow.Range), sgn > 0 ? 0f : 180f);
            HallThrow.QaAutoAim(false);
            HallThrow.Do("test", new Vector3(0f, 0f, sgn));
            yield return Wait(6f);
            Summary();
        }
    }

    public sealed class OnePitTrainDriver : OnePit8bDriver""",1)
open(p,'w',encoding='utf-8').write(s)
