import re,glob,statistics as st
V='v6k/A/ab'
def ch(f):
    d={}
    for ln in open(f,errors='replace'):
        m=re.match(r'([0-9.]+)\tchapter:(\d+)',ln)
        if m and int(m.group(2)) not in d: d[int(m.group(2))]=float(m.group(1))
    return d
def steps(logf):
    out=[]
    for ln in open(logf,errors='replace'):
        m=re.search(r'\[onepit\] pit_step .*?n=(\d+).*?ch_t=([\d.]+)',ln)
        if m: out.append((int(m.group(1)),float(m.group(2))))
    return out
res={'k':{}, 'b':{}}
for g in ('k','b'):
    for s in range(5501,5509):
        f=f'{V}/{g}_s{s}_events.txt'; d=ch(f)
        lg=f'{V}/{g}_s{s}.log'
        stp=dict(steps(lg))
        res[g][s]=(d.get(2), stp)
print('seed  b(мин)  k(мин)  Δ')
D=[]
for s in range(5501,5509):
    b=res['b'][s][0]; k=res['k'][s][0]
    print(s, round(b/60,1) if b else None, round(k/60,1) if k else None, round((k-b)/60,1) if b and k else None)
    if b and k: D.append((k-b)/60)
mb=st.median([res['b'][s][0]/60 for s in res['b'] if res['b'][s][0]]); mk=st.median([res['k'][s][0]/60 for s in res['k'] if res['k'][s][0]])
print('медиана',round(mb,1),round(mk,1), 'Δ ср', round(st.mean(D),2))
# ступени
allk=[];allb=[]
for n in range(1,9):
    kb=[res['b'][s][1].get(n) for s in res['b'] if res['b'][s][1].get(n)]
    kk=[res['k'][s][1].get(n) for s in res['k'] if res['k'][s][1].get(n)]
    print('step',n, round(st.median(kb)/60,1) if kb else None, round(st.median(kk)/60,1) if kk else None)
