    /// конфликтом с PRD коробок, NB 302–313 п. 19 и NB 978–1000 п. 70). Лестница растянута до миллиардов: к главе III доход 1,5–1,85 M/мин
    /// (NB 1157), $1M проходится в главе II. Пороги — по замеру фермы v6j (newbie-бот, 4 сида; «in» леджера — iter8d/v6k/M/passport-thresholds.md):
    /// $1K ≈ 8 мин, $25K ≈ 25, $100K ≈ 45, $500K ≈ 55, $2,5M ≈ 75, $10M ≈ 90, $50M ≈ 100, $250M ≈ 110, $1B ≈ 110–120, $5B ≈ 125–135, $25B ≈ 130+.
    /// Шаг ×2,5–×5 (полдекады): веха каждые 5–15 мин по ходу игры.
    public static class EarnedTitles
    {
        /// Пороги (EarnedTotal ≥) и названия; индекс 0 — стартовый титул (порог 0). Возрастающие.
        public static readonly double[] At =
        {
            0, 1e3, 5e3, 2.5e4, 1e5, 5e5, 2.5e6, 1e7, 5e7, 2.5e8, 1e9, 5e9, 2.5e10,
        };
        public static readonly string[] Names =
        {
            "Утиная лавочка", "Гараж с утятами", "Утиная артель", "Пластиковый картель", "Кряк и сыновья", "Барон пружин", "Утиный концерн",
            "Магнат Одной Ямы", "Король конвейера", "Император Ямы", "МИЛЛИАРДЕР", "Утиный олигарх", "Повелитель Ям",
        };
        /// Индекс титула «Миллиардер» (порог 1e9): большой баннер.
        public const int Billionaire = 10;

        /// Сколько раз веха объявлена в этом процессе и последний объявленный индекс (тесты, ферма).
        public static int Announced, LastIdx = -1;

        [UnityEngine.RuntimeInitializeOnLoadMethod(UnityEngine.RuntimeInitializeLoadType.SubsystemRegistration)]
        static void ResetStatics() { Announced = 0; LastIdx = -1; }

        /// Индекс титула по сумме (0 — стартовый).
        public static int IndexOf(double earned)
        {
            int i = 0;
            while (i + 1 < At.Length && earned >= At[i + 1]) i++;
            return i;
        }

        public static string NameOf(int i) => Names[System.Math.Max(0, System.Math.Min(i, Names.Length - 1))];
        /// Порог следующего титула; 0 — титулы кончились.
        public static double NextAt(int i) => i + 1 < At.Length ? At[i + 1] : 0.0;
    }
}
