using UnityEngine;

namespace Pitt.OnePit
{
    /// v6k (M): кадры приёмки (только захват, `-pittCapShow passport|passport_card|passport_full|ticker|shelf|shelf_full`, через HallUx.CapShow).
    /// - passport / passport_card / passport_full — лист «Прокачки» на вкладке «Яма» (или карточка «Паспорт утковода») при заданных счётчиках;
    /// - ticker — герой у северной стены: сумма табло подведена под порог $25 000 и через 3 с пересекает его (кадры реакции табло);
    /// - shelf / shelf_full — кот приходит сразу (строится будка с полкой), герой у будки; shelf — 3-я диковинка появляется через 4 с.
    public static class HallCapV6k
    {
        static string _what;
        static double _at = -1;
        static int _stage;

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        static void ResetStatics() { _what = null; _at = -1; _stage = 0; }

        public static bool Handles(string what) =>
            what == "passport" || what == "passport_card" || what == "passport_full" || what == "ticker" || what == "shelf" || what == "shelf_full";

        public static void Start(string what)
        {
            _what = what; _stage = 0; _at = OnePitState.HallTimeD;
            switch (what)
            {
                case "passport": case "passport_card": case "passport_full":
                    if (what == "passport_full") { HallPassport.Count[0] = 5200; HallPassport.Count[1] = 120; HallPassport.Count[2] = 410; }
                    else { HallPassport.Count[0] = 640; HallPassport.Count[1] = 37; HallPassport.Count[2] = 0; }
                    HallUx.Flags |= HallDuckFeedback.BlueSeen | HallDuckFeedback.GoldSeen | (what == "passport_full" ? HallDuckFeedback.VioletSeen : 0);
                    HallUpgSheet.Open("cap");
                    HallUpgSheet.SelectTab(HallOffers.TabPit);
                    if (what == "passport_card") HallUpgSheet.OpenDuckCard();
                    _what = null;
                    break;
                case "ticker":
                    Put(BoardView());
                    break;
                case "shelf": case "shelf_full":
                    HallCat.TestForce = true;
                    HallCrates.Collected = what == "shelf_full" ? 100 : 20;
                    break;
            }
        }

        static Vector3 BoardView()
        {
            var gb = GoalBoard.Current;
            return gb ? new Vector3(gb.transform.position.x, 0f, gb.transform.position.z - 7f) : Vector3.zero;
        }

        static void Put(Vector3 p)
        {
            if (Game.Player == null) return;
            Game.Player.Teleport(p, 0f);
            Game.CamRig?.Snap();
        }

        /// Каждый кадр (HallUx.CapShow): этапы по игровому времени от Start.
        public static void Tick()
        {
            if (_what == null) return;
            double dt = OnePitState.HallTimeD - _at;
            var st = Game.State;
            if (st == null) return;
            if (_what == "ticker")
            {
                if (_stage == 0 && dt >= 1.0)
                {
                    _stage = 1;
                    double need = 24800.0 - st.EarnedTotal;
                    if (need > 0) st.AddMoney(need);
                }
                else if (_stage == 1 && dt >= 4.5) { _stage = 2; st.AddMoney(500.0); }
                else if (_stage == 2 && dt >= 9.0) _what = null;
            }
            else if (_what == "shelf" || _what == "shelf_full")
            {
                if (_stage == 0 && HallShelf.I != null && Game.Player != null)
                {
                    _stage = 1; _at = OnePitState.HallTimeD;
                    Put(HallCat.KennelPos + new Vector3(2.6f, 0f, 1.2f));   // справа и чуть севернее будки: полка за ней, будка и вход в кадре
                    if (_what == "shelf_full") _what = null;
                }
                else if (_stage == 1 && dt >= 4.0)
                {
                    _stage = 2;
                    HallCrates.Collected = 30;
                    HallShelf.OnCrate(30);
                    _what = null;
                }
            }
        }
    }
}
